<div class="mb-6"><p class="text-sm font-medium text-blue-600">Asistencia</p><h1 class="text-2xl font-bold">Justificaciones e incidencias</h1></div>
<section class="grid gap-5 lg:grid-cols-[360px_1fr]"><article class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><h2 class="font-semibold">Registrar incidencia</h2><form method="post" action="index.php?url=incidencia_guardar" class="mt-4 space-y-3"><?= campoCsrf() ?><select required name="id_asistencia" class="form-input mt-0"><option value="">Seleccione asistencia</option><?php foreach($asistencias as $a): ?><option value="<?= $a['id_asistencia'] ?>"><?= htmlspecialchars($a['fecha'].' · '.$a['persona'].' · '.$a['estado']) ?></option><?php endforeach; ?></select><select name="tipo" class="form-input mt-0"><option value="JUSTIFICACION_FALTA">Justificación de falta</option><option value="JUSTIFICACION_TARDANZA">Justificación de tardanza</option><option value="PERMISO">Permiso</option><option value="LICENCIA">Licencia</option><option value="OBSERVACION">Observación</option></select><textarea required name="motivo" rows="4" class="form-input mt-0" placeholder="Detalle y sustento"></textarea><button class="w-full rounded-xl bg-blue-600 py-2.5 text-sm font-semibold text-white">Registrar</button></form></article><article class="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm"><div class="overflow-x-auto"><table data-datatable data-page-options="5,10,25,50" data-order="1:desc" class="min-w-full text-sm"><thead class="bg-slate-50 text-left text-xs uppercase text-slate-500"><tr><th class="px-4 py-3">Persona</th><th class="px-4 py-3">Fecha</th><th class="px-4 py-3">Tipo</th><th class="px-4 py-3">Estado</th></tr></thead><tbody class="divide-y divide-slate-100"><?php foreach($incidencias as $i): $estado=$i['estado']; $colorEstado=['PUNTUAL'=>'bg-emerald-100 text-emerald-700','TARDANZA'=>'bg-amber-100 text-amber-800','FALTA'=>'bg-red-100 text-red-700','JUSTIFICADO'=>'bg-sky-100 text-sky-700','PERMISO'=>'bg-violet-100 text-violet-700','INCOMPLETO'=>'bg-orange-100 text-orange-700','LICENCIA'=>'bg-slate-200 text-slate-700','SALIDA_ANTICIPADA'=>'bg-pink-100 text-pink-700'][$estado]??'bg-slate-100 text-slate-700'; ?><tr><td class="px-4 py-3 font-medium"><?= htmlspecialchars($i['persona']) ?></td><td class="px-4 py-3 text-slate-600"><?= htmlspecialchars($i['fecha']) ?></td><td class="px-4 py-3"><?= htmlspecialchars($i['tipo']) ?></td><td class="px-4 py-3"><span class="inline-flex rounded-full px-2.5 py-1 text-xs font-semibold <?= $colorEstado ?>"><?= htmlspecialchars($estado) ?></span></td></tr><?php endforeach; ?><?php if(!$incidencias): ?><tr><td colspan="4" class="px-5 py-12 text-center text-slate-500">No hay incidencias registradas.</td></tr><?php endif; ?></tbody></table></div></article></section>
